37		_ = h.Info()
38		if err := h.HealthCheck(context.Background()); err != claudetui.ErrNotYetImplemented {
39			t.Errorf("HealthCheck returned %v, want ErrNotYetImplemented", err)
40		}
41		if _, err := h.Execute(context.Background(), harnesses.ExecuteRequest{}); err != claudetui.ErrNotYetImplemented {
42			t.Errorf("Execute returned %v, want ErrNotYetImplemented", err)
43		}
44		if _, err := h.QuotaStatus(context.Background(), time.Now()); err != claudetui.ErrNotYetImplemented {
