69	// checkCompileTimeAssertions verifies the var _ block exists in harness.go.
70	func checkCompileTimeAssertions(t *testing.T) {
71		t.Helper()
72		repoRoot := findRepoRoot(t)
73		fset := token.NewFileSet()
74		path := filepath.Join(repoRoot, "internal", "harnesses", "claude-tui", "harness.go")
75		file, err := parser.ParseFile(fset, path, nil, 0)
76		if err != nil {
77			t.Fatalf("parse %s: %v", path, err)
78		}
79	
80		found := make(map[string]bool)
81		ast.Inspect(file, func(n ast.Node) bool {
82			if decl, ok := n.(*ast.GenDecl); ok && decl.Tok == token.VAR {
83				for _, spec := range decl.Specs {
84					if vs, ok := spec.(*ast.ValueSpec); ok {
85						// Check if this is a blank identifier assignment with a type.
86						if len(vs.Names) == 1 && vs.Names[0].Name == "_" && vs.Type != nil {
87							// The Type field contains the interface type being asserted.
88							if sel, ok := vs.Type.(*ast.SelectorExpr); ok {
89								if ident, ok := sel.X.(*ast.Ident); ok {
90									typ := fmt.Sprintf("%s.%s", ident.Name, sel.Sel.Name)
91									found[typ] = true
92								}
93							}
94						}
95					}
96				}
97			}
98			return true
99		})
100	
101		required := []string{
102			"harnesses.Harness",
103			"harnesses.QuotaHarness",
104			"harnesses.AccountHarness",
105			"harnesses.ModelDiscoveryHarness",
106		}
107		for _, req := range required {
108			if !found[req] {
109				t.Errorf("missing compile-time assertion for %s", req)
110			}
111		}
112	}
