27	func ReadClaudeModelDiscoveryViaPTY(timeout time.Duration, opts ...QuotaPTYOption) (harnesses.ModelDiscoverySnapshot, error) {
28		cfg := quotaPTYOptions{binary: "claude"}
29		for _, opt := range opts {
30			if opt != nil {
31				opt(&cfg)
32			}
33		}
34		var snapshot harnesses.ModelDiscoverySnapshot
35		_, err := ptyquota.Run(context.Background(), ptyquota.Config{
36			HarnessName:  "claude",
37			Binary:       cfg.binary,
38			Args:         cfg.args,
39			Workdir:      cfg.workdir,
40			Env:          cfg.env,
41			Command:      "/model\r",
42			ReadyMarkers: []string{"❯", "> "},
43			DoneWhen:     claudeModelDiscoveryComplete,
44			Timeout:      timeout,
45			Size:         session.Size{Rows: 50, Cols: 220},
46			CassetteDir:  cfg.cassetteDir,
47			Discovery: func(text string) (cassette.DiscoveryRecord, error) {
48				snapshot = claudeDiscoveryFromText(text, "pty")
49				if len(snapshot.Models) == 0 {
50					return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in claude /model output")
51				}
52				return discoveryRecord(snapshot), nil
53			},
54		})
55		if err != nil {
56			return harnesses.ModelDiscoverySnapshot{}, err
57		}
58		if len(snapshot.Models) == 0 {
59			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in claude /model output")
60		}
61		return snapshot, nil
62	}
