86	func readClaudeReasoningFromHelp(ctx context.Context, binary string, args ...string) ([]string, error) {
87		if binary == "" {
88			binary = "claude"
89		}
90		if len(args) == 0 {
91			args = []string{"--help"}
92		}
93		cmd := exec.CommandContext(ctx, binary, args...)
94		out, err := cmd.CombinedOutput()
95		if err != nil {
96			return nil, fmt.Errorf("claude help: %w", err)
97		}
98		levels := parseClaudeReasoningLevels(string(out))
99		if len(levels) == 0 {
100			return nil, fmt.Errorf("claude help did not expose --effort levels")
101		}
102		return levels, nil
103	}
