14	// claudeQuotaFreshness is the constant freshness window for claude quota
15	// evidence. Mirrors defaultClaudeQuotaStaleAfter (kept as a separate name
16	// so the CONTRACT-004 method has a stable, contract-named constant).
17	const claudeQuotaFreshness = defaultClaudeQuotaStaleAfter
18	
19	// claudeAccountFreshness is the constant freshness window for claude
20	// account evidence. Claude embeds account info in its quota probe so the
21	// account refresh cadence matches quota.
22	const claudeAccountFreshness = defaultClaudeQuotaStaleAfter
23	
24	// supportedLimitIDs is the stable public set of Windows[].LimitID values
25	// claude's quota probe emits. Mirrored in doc.go for human readers.
26	var supportedLimitIDs = []string{
27		"session",
28		"weekly-all",
29		"weekly-sonnet",
30		"extra",
31	}
32	
33	// supportedAliases is the stable public set of family aliases
34	// ResolveModelAlias recognizes. Mirrored in doc.go for human readers.
35	var supportedAliases = []string{"sonnet", "opus", "haiku"}
36	
37	// refreshGroup serializes concurrent RefreshQuota / RefreshAccount calls
38	// across all *Runner instances. Per CONTRACT-004 invariant #6 Runners are
39	// stateless wrappers — sharing the singleflight group at package scope
40	// keeps single-flight semantics correct when callers construct fresh
41	// runner instances per call (which the dispatcher does today).
42	var refreshGroup singleflight.Group
43	
44	// QuotaProbeFunc is the signature of the PTY-quota probe that
45	// Runner.RefreshQuota delegates to. Exposing it as a named type keeps
46	// the SetCaptureForTest seam decoupled from the internal ptyquota
47	// package; the test seam discards the ptyquota.Result that the live
48	// probe returns.
49	type QuotaProbeFunc func(ctx context.Context, timeout time.Duration, opts ...QuotaPTYOption) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error)
50	
51	// captureQuotaProbe is the live PTY probe used by RefreshQuota. It is a
52	// package-level variable so tests can swap it via SetCaptureForTest
53	// without spawning the claude binary. The default delegates to
54	// captureClaudeQuotaViaPTY and discards the ptyquota.Result.
55	var captureQuotaProbe QuotaProbeFunc = func(ctx context.Context, timeout time.Duration, opts ...QuotaPTYOption) ([]harnesses.QuotaWindow, *harnesses.AccountInfo, error) {
56		windows, account, _, err := captureClaudeQuotaViaPTY(ctx, timeout, opts...)
57		return windows, account, err
58	}
59	
60	// SetCaptureForTest swaps the package-level PTY probe used by
61	// Runner.RefreshQuota and returns a restore function. Production code
62	// MUST NOT call this — it exists so service-level tests can inject
63	// deterministic PTY responses while exercising the real cache I/O
64	// inside Runner.refreshQuotaLocked. The call also forgets any
65	// in-flight RefreshQuota cohort so the next caller runs a fresh
66	// single-flight execution against the new probe instead of piggybacking
67	// on a prior test's probe.
68	func SetCaptureForTest(fn QuotaProbeFunc) func() {
69		prev := captureQuotaProbe
70		captureQuotaProbe = fn
71		refreshGroup.Forget("claude:refresh-quota")
72		return func() {
73			captureQuotaProbe = prev
74			refreshGroup.Forget("claude:refresh-quota")
75		}
76	}
77	
78	// QuotaStatus implements harnesses.QuotaHarness. It reads the cached
79	// snapshot owned by this harness and projects it onto QuotaStatus. A
80	// missing or undecodable cache is reported as State=QuotaUnavailable on
81	// a valid QuotaStatus value (no error) per CONTRACT-004 §"Errors are
82	// reserved for call failure."
83	func (r *Runner) QuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
84		if err := ctx.Err(); err != nil {
85			return harnesses.QuotaStatus{}, err
86		}
87		snap, ok := readClaudeQuota()
88		if !ok || snap == nil {
89			return harnesses.QuotaStatus{
90				Source:            "cache",
91				State:             harnesses.QuotaUnavailable,
92				RoutingPreference: harnesses.RoutingPreferenceUnknown,
93				Reason:            "no cached snapshot",
94			}, nil
95		}
96		return claudeQuotaStatusFromSnapshot(snap, now), nil
97	}
98	
99	// RefreshQuota implements harnesses.QuotaHarness. It probes the claude
100	// CLI via PTY unconditionally and persists the result through the
101	// harness's owned cache. Single-flight per harness: concurrent callers
102	// share one cohort and observe the just-written cached state. Probe
103	// failure (binary missing, PTY error, parse failure) is reported as
104	// State=QuotaUnavailable on a valid QuotaStatus value, not as an error.
105	func (r *Runner) RefreshQuota(ctx context.Context) (harnesses.QuotaStatus, error) {
106		if err := ctx.Err(); err != nil {
107			return harnesses.QuotaStatus{}, err
108		}
109		v, err, _ := refreshGroup.Do("claude:refresh-quota", func() (any, error) {
110			return r.refreshQuotaLocked(ctx), nil
111		})
112		if err != nil {
113			return harnesses.QuotaStatus{}, err
114		}
115		return v.(harnesses.QuotaStatus), nil
116	}
117	
118	// refreshQuotaLocked is the single-flight critical section. It probes
119	// PTY, writes the cache on success, and returns the projected status.
120	// Probe failure is folded into State=QuotaUnavailable.
121	func (r *Runner) refreshQuotaLocked(ctx context.Context) harnesses.QuotaStatus {
122		now := time.Now()
123		timeout := claudeQuotaFreshness
124		if deadline, ok := ctx.Deadline(); ok {
125			remaining := time.Until(deadline)
126			if remaining > 0 && remaining < timeout {
127				timeout = remaining
128			}
129		}
130		var opts []QuotaPTYOption
131		if r.Binary != "" {
132			opts = append(opts, WithQuotaPTYCommand(r.Binary))
133		}
134		windows, account, err := captureQuotaProbe(ctx, timeout, opts...)
135		if err != nil {
136			state := harnesses.QuotaUnavailable
137			reason := err.Error()
138			if strings.Contains(strings.ToLower(reason), "not found in path") {
139				state = harnesses.QuotaUnauthenticated
140			}
141			return harnesses.QuotaStatus{
142				Source:            "pty",
143				CapturedAt:        now.UTC(),
144				State:             state,
145				RoutingPreference: harnesses.RoutingPreferenceUnknown,
146				Reason:            reason,
147			}
148		}
149		snap := claudeQuotaSnapshotFromWindows(windows, account)
150		if path, pathErr := claudeQuotaCachePath(); pathErr == nil {
151			_ = writeClaudeQuota(path, snap)
152		}
153		return claudeQuotaStatusFromSnapshot(&snap, now)
154	}
