215	// ResolveModelAlias implements harnesses.ModelDiscoveryHarness. Returns
216	// harnesses.ErrAliasNotResolvable when the supplied family is not a
217	// recognized claude alias or when the supplied discovery snapshot has
218	// no concrete model matching the family.
219	func (r *Runner) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
220		normalized := strings.ToLower(strings.TrimSpace(family))
221		if !isSupportedClaudeAlias(normalized) {
222			return "", harnesses.ErrAliasNotResolvable
223		}
224		resolved := resolveClaudeFamilyAlias(normalized, snapshot)
225		if resolved == "" {
226			return "", harnesses.ErrAliasNotResolvable
227		}
228		return resolved, nil
229	}
