245	// claudeQuotaStatusFromSnapshot projects the per-harness snapshot onto
246	// harnesses.QuotaStatus, deriving State and RoutingPreference via the
247	// existing internal routing helper so today's "PreferClaude +
248	// freshness" semantics map cleanly onto CONTRACT-004's RoutingPreference
249	// enum.
250	func claudeQuotaStatusFromSnapshot(snap *claudeQuotaSnapshot, now time.Time) harnesses.QuotaStatus {
251		decision := decideClaudeQuotaRouting(snap, now, claudeQuotaFreshness)
252		pref, state := mapClaudeRoutingPreference(decision)
253		status := harnesses.QuotaStatus{
254			Source:            snap.Source,
255			CapturedAt:        snap.CapturedAt,
256			Fresh:             decision.Fresh,
257			Age:               decision.Age,
258			State:             state,
259			Windows:           append([]harnesses.QuotaWindow(nil), snap.Windows...),
260			RoutingPreference: pref,
261			Reason:            quotaReasonForProjection(decision, state),
262		}
263		if snap.Account != nil {
264			acct := claudeAccountSnapshotFromQuotaSnapshot(snap, now)
265			status.Account = &acct
266		}
267		return status
268	}
269	
270	// quotaReasonForProjection trims the routing decision's diagnostic
271	// reason so QuotaStatus.Reason carries information only when it adds
272	// value beyond the State enum. The trivial QuotaOK success path
273	// ("fresh snapshot has headroom") is suppressed so the public Status
274	// string matches the contract-003 fixture (bare "ok"). All non-OK
275	// states keep the decision reason because it surfaces why the state is
276	// not ok (stale snapshot, incomplete account, exhausted window).
277	func quotaReasonForProjection(decision claudeQuotaRoutingDecision, state harnesses.QuotaStateValue) string {
278		if state == harnesses.QuotaOK {
279			return ""
280		}
281		return decision.Reason
282	}
283	
284	// mapClaudeRoutingPreference translates today's PreferClaude+freshness
285	// decision into the CONTRACT-004 (RoutingPreference, QuotaStateValue)
286	// pair. Legacy semantics: missing snapshot ⇒ Unavailable/Unknown;
287	// stale ⇒ Stale/Blocked ("assume limited"); fresh+PreferClaude ⇒
288	// OK/Available; fresh+!PreferClaude ⇒ Blocked/Blocked.
289	func mapClaudeRoutingPreference(d claudeQuotaRoutingDecision) (harnesses.RoutingPreference, harnesses.QuotaStateValue) {
290		if !d.SnapshotPresent {
291			return harnesses.RoutingPreferenceUnknown, harnesses.QuotaUnavailable
292		}
293		if !d.Fresh {
294			return harnesses.RoutingPreferenceBlocked, harnesses.QuotaStale
295		}
296		if d.PreferClaude {
297			return harnesses.RoutingPreferenceAvailable, harnesses.QuotaOK
298		}
299		return harnesses.RoutingPreferenceBlocked, harnesses.QuotaBlocked
300	}
301	
302	// claudeAccountSnapshotFromQuotaSnapshot derives an AccountSnapshot from
303	// the quota cache's embedded Account field. Plan-type "unknown" (written
304	// by markClaudeQuotaExhaustedFromMessage on runtime errors) is reported
305	// as unauthenticated evidence rather than positive authentication.
306	func claudeAccountSnapshotFromQuotaSnapshot(snap *claudeQuotaSnapshot, now time.Time) harnesses.AccountSnapshot {
307		out := harnesses.AccountSnapshot{
308			Source:     "cache",
309			CapturedAt: snap.CapturedAt,
310			Fresh:      isClaudeQuotaFresh(snap, now, claudeAccountFreshness),
311		}
312		if snap.Account == nil {
313			return out
314		}
315		plan := strings.TrimSpace(snap.Account.PlanType)
316		out.PlanType = plan
317		out.Email = snap.Account.Email
318		out.OrgName = snap.Account.OrgName
319		switch {
320		case plan == "" || strings.EqualFold(plan, "unknown"):
321			out.Unauthenticated = true
322		default:
323			out.Authenticated = true
324		}
325		return out
326	}
