328	// Compile-time interface satisfaction.
329	var (
330		_ harnesses.Harness               = (*Runner)(nil)
331		_ harnesses.QuotaHarness          = (*Runner)(nil)
332		_ harnesses.AccountHarness        = (*Runner)(nil)
333		_ harnesses.ModelDiscoveryHarness = (*Runner)(nil)
334	)
