// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness.
// It attempts to load a snapshot from a cassette (test fixture) or live PTY discovery.
// On failure, it returns ErrModelDiscoveryEvidenceMissing (no static fallback allowed).
func (h *Harness) DefaultModelSnapshot() harnesses.ModelDiscoverySnapshot {
	// Try to load from test cassette if available (for testing only).
	if snapshot, err := loadModelDiscoveryCassette(); err == nil {
		return snapshot
	}
