		FreshnessWindow string   `json:"freshness_window"`
		Detail          string   `json:"detail"`
	}

	var rec discoveryRecord
	if err := json.Unmarshal(data, &rec); err != nil {
		return harnesses.ModelDiscoverySnapshot{}, err
	}

	capturedAt, _ := time.Parse(time.RFC3339, rec.CapturedAt)
	if capturedAt.IsZero() {
		capturedAt = time.Now().UTC()
	}

	return harnesses.ModelDiscoverySnapshot{
		CapturedAt:      capturedAt,
		Models:          append([]string(nil), rec.Models...),
		ReasoningLevels: append([]string(nil), rec.ReasoningLevels...),
		Source:          rec.Source,
		FreshnessWindow: rec.FreshnessWindow,
		Detail:          rec.Detail,
	}, nil
}

// findRepoRoot searches for the repository root by walking up the directory tree
// looking for go.mod.
func findRepoRoot(t *testing.T) string {
	t.Helper()
	cwd, err := filepath.Abs(".")
	if err != nil {
		t.Fatalf("get absolute path: %v", err)
	}

	for {
		if _, err := os.Stat(filepath.Join(cwd, "go.mod")); err == nil {
			return cwd
		}
		parent := filepath.Dir(cwd)
		if parent == cwd {
			t.Fatal("could not find go.mod in any parent directory")
		}
		cwd = parent
	}
}

