// TestClaudeTuiDefaultModelSnapshotMissingEvidence asserts that DefaultModelSnapshot
// returns a snapshot with empty models and error detail when PTY discovery fails or
// is unavailable (per the no-static-fallback principle: no fallback literal snapshot).
func TestClaudeTuiDefaultModelSnapshotMissingEvidence(t *testing.T) {
	h := &claudetui.Harness{}
	snapshot := h.DefaultModelSnapshot()

	// DefaultModelSnapshot should always return a snapshot (not an error),
	// but with empty models to signal missing evidence.
	if snapshot.Source != "pty-error" {
		t.Errorf("Source: got %q, want %q", snapshot.Source, "pty-error")
	}

	// Models should be empty to indicate discovery failed.
	if len(snapshot.Models) != 0 {
		t.Errorf("Models: got %d, want 0 (empty)", len(snapshot.Models))
	}

	// ReasoningLevels should be empty.
	if len(snapshot.ReasoningLevels) != 0 {
		t.Errorf("ReasoningLevels: got %d, want 0 (empty)", len(snapshot.ReasoningLevels))
	}

	// Detail should explain the error.
	if !strings.Contains(snapshot.Detail, "not yet implemented") {
		t.Errorf("Detail: got %q, want substring 'not yet implemented'", snapshot.Detail)
	}
}

